package com.company.tpm.assignment;import org.junit.jupiter.api.*;class TrainingStatusEngineTest{private final TrainingStatusEngine engine=new TrainingStatusEngine();@Test void acceptsValid(){Assertions.assertDoesNotThrow(()->engine.validate(TrainingAssignment.Status.ASSIGNED,TrainingAssignment.Status.SCHEDULED));}@Test void rejectsInvalid(){Assertions.assertThrows(IllegalStateException.class,()->engine.validate(TrainingAssignment.Status.COMPLETED,TrainingAssignment.Status.ASSIGNED));}}